mapper.insert:
INSERT INTO ai_generated_card ( session_id, status, user_id, title, options, answer, explanation, card_type, card_difficulty, card_mastery, question_type, name, create_time
) VALUES
( #{item.sessionId}, #{item.status}, #{item.userId}, #{item.title}, #{item.options, typeHandler=com.baomidou.mybatisplus.extension.handlers.JacksonTypeHandler}, #{item.answer}, #{item.explanation}, #{item.cardType}, #{item.cardDifficulty}, #{item.cardMastery}, #{item.questionType}, #{item.name}, NOW() )
